from collections import Counter, deque

def rect_transform(grid, min_area=4, min_density=0.45):
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); boxes=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        for a,b in q:
          cells.append((a,b))
          for na,nb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
            if 0<=na<h and 0<=nb<w and (na,nb) not in seen and grid[na][nb]==color:
              seen.add((na,nb)); q.append((na,nb))
        r0=min(a for a,b in cells); r1=max(a for a,b in cells); c0=min(b for a,b in cells); c1=max(b for a,b in cells)
        area=(r1-r0+1)*(c1-c0+1)
        if area>=min_area and len(cells)/area>=min_density:
          boxes.append((color,r0,r1,c0,c1,len(cells),area))
    out=[[bg]*w for _ in range(h)]
    # larger boxes first; smaller overlays nested objects
    for color,r0,r1,c0,c1,n,area in sorted(boxes,key=lambda x:-x[-1]):
      for a in range(r0,r1+1):
       for b in range(c0,c1+1): out[a][b]=color
    return out, boxes
